sys_ui_page.client_script:
window.addEventListener(
    'load',
    function() {

        loadAttendanceInsights();

    }
);


// =============================================================
// LOAD VERIFIED MANAGER INSIGHTS
// =============================================================
function loadAttendanceInsights() {

    fetch(
        '/api/x_1760545_smarta_0/smartattend_api/manager-insights',
        {
            method: 'GET',

            credentials: 'same-origin',

            headers: buildHeaders(false)
        }
    )

    .then(function(response) {

        return response.text()
            .then(function(text) {

                var data = null;

                try {

                    data =
                        JSON.parse(text);

                }
                catch (e) {

                    throw new Error(
                        'Invalid manager insight response.'
                    );

                }


                return {
                    ok: response.ok,
                    status: response.status,
                    data: data
                };

            });

    })

    .then(function(result) {

        if (
            !result.ok ||
            !result.data ||
            !result.data.result ||
            !result.data.result.success
        ) {

            throw new Error(
                'Unable to load attendance insights.'
            );

        }


        var insightData =
            result.data.result;


        // Show trusted statistics first
        renderInsights(
            insightData
        );


        // Then request Gemini recommendation
        loadAIManagerSummary(
            insightData
        );

    })

    .catch(function(error) {

        showPageError(
            error.message ||
            'Unable to load attendance insights.'
        );

    });

}


// =============================================================
// HEADERS
// =============================================================
function buildHeaders(
    includeJson
) {

    var headers = {};


    if (includeJson) {

        headers[
            'Content-Type'
        ] =
            'application/json';

    }


    // g_ck may not always be exposed by every mobile web view.
    // credentials:same-origin still carries the logged-in session.
    if (
        typeof window.g_ck !==
            'undefined' &&
        window.g_ck
    ) {

        headers[
            'X-UserToken'
        ] =
            window.g_ck;

    }


    return headers;

}


// =============================================================
// RENDER VERIFIED ANALYTICS
// =============================================================
function renderInsights(data) {

    var loadingBox =
        document.getElementById(
            'loadingBox'
        );


    if (loadingBox) {

        loadingBox.style.display =
            'none';

    }


    setDisplay(
        'managerBox',
        'block'
    );


    setDisplay(
        'summaryGrid',
        'grid'
    );


    setDisplay(
        'aiSummaryBox',
        'block'
    );


    setDisplay(
        'employeeTitle',
        'block'
    );


    // ---------------------------------------------------------
    // MANAGER
    // ---------------------------------------------------------
    setText(
        'managerName',
        data.manager ||
        'Manager'
    );


    var period =
        data.period || {};


    setText(
        'periodText',

        'Last ' +
        (period.days || 7) +
        ' days • ' +
        formatDate(
            period.from
        ) +
        ' to ' +
        formatDate(
            period.to
        )
    );


    // ---------------------------------------------------------
    // SUMMARY
    // ---------------------------------------------------------
    var summary =
        data.summary || {};


    setText(
        'totalEmployees',
        summary.total_employees || 0
    );


    setText(
        'attendanceRecords',
        summary.total_attendance_records || 0
    );


    setText(
        'lateRecords',
        summary.late_records || 0
    );


    setText(
        'insufficientRecords',
        summary.insufficient_hours_records || 0
    );


    setText(
        'averageMinutes',
        summary.average_working_minutes || 0
    );


    // ---------------------------------------------------------
    // SAFE FALLBACK FIRST
    // ---------------------------------------------------------
    setAISummaryTitle(
        '✨ Manager Insight Summary'
    );


    setAISummaryText(
        buildManagerSummary(
            data
        )
    );


    setAISummaryMeta(
        'Verified SmartAttend attendance statistics'
    );


    // ---------------------------------------------------------
    // EMPLOYEES
    // ---------------------------------------------------------
    renderEmployees(
        data.employees || []
    );

}


// =============================================================
// GEMINI AI MANAGER SUMMARY
// =============================================================
function loadAIManagerSummary(data) {

    setAISummaryTitle(
        '✨ AI Manager Summary'
    );


    setAISummaryText(
        'Generating AI attendance recommendation...'
    );


    setAISummaryMeta(
        'Gemini is analysing verified SmartAttend statistics'
    );


    fetch(
        '/api/x_1760545_smarta_0/smartattend_api/ai-summary',
        {
            method: 'POST',

            credentials:
                'same-origin',

            headers:
                buildHeaders(true),

            body:
                JSON.stringify({

                    summary:
                        data.summary || {},

                    period:
                        data.period || {},

                    employees:
                        data.employees || []

                })
        }
    )

    .then(function(response) {

        return response.text()
            .then(function(text) {

                var json = null;


                try {

                    json =
                        JSON.parse(text);

                }
                catch (e) {

                    return {

                        ok: false,

                        status:
                            response.status,

                        parse_error:
                            true,

                        raw:
                            text

                    };

                }


                return {

                    ok:
                        response.ok,

                    status:
                        response.status,

                    data:
                        json

                };

            });

    })

    .then(function(result) {

        // -----------------------------------------------------
        // INVALID RESPONSE
        // -----------------------------------------------------
        if (
            result.parse_error
        ) {

            console.warn(
                'SmartAttend AI invalid response:',
                result.raw
            );


            showFallbackSummary(
                data,
                'AI response could not be parsed'
            );

            return;
        }


        var apiResult =
            result.data &&
            result.data.result
                ? result.data.result
                : null;


        // -----------------------------------------------------
        // GEMINI SUCCESS
        // -----------------------------------------------------
        if (
            result.ok &&
            apiResult &&
            apiResult.success &&
            apiResult.ai_text
        ) {

            setAISummaryTitle(
                '✨ AI Manager Summary'
            );


            setAISummaryText(
                cleanAIText(
                    apiResult.ai_text
                )
            );


            setAISummaryMeta(
                'Generated by ' +
                (
                    apiResult.provider ||
                    'Gemini'
                ) +
                ' • ' +
                (
                    apiResult.model ||
                    'gemini-3.6-flash'
                )
            );


            return;

        }


        // -----------------------------------------------------
        // AI PROVIDER FAILURE
        // -----------------------------------------------------
        console.warn(
            'SmartAttend AI fallback:',
            apiResult
        );


        var fallbackReason =
            'AI temporarily unavailable';


        if (
            apiResult &&
            apiResult.provider_status
        ) {

            fallbackReason +=
                ' • HTTP ' +
                apiResult.provider_status;

        }


        showFallbackSummary(
            data,
            fallbackReason
        );

    })

    .catch(function(error) {

        console.warn(
            'Gemini AI request failed:',
            error
        );


        showFallbackSummary(
            data,
            'AI request unavailable'
        );

    });

}


// =============================================================
// CLEAN AI RESPONSE
// =============================================================
function cleanAIText(text) {

    if (!text) {

        return '';

    }


    var cleaned =
        String(text);


    // Remove common markdown formatting.
    cleaned =
        cleaned.replace(
            /\*\*/g,
            ''
        );


    cleaned =
        cleaned.replace(
            /^###\s*/gm,
            ''
        );


    cleaned =
        cleaned.replace(
            /^##\s*/gm,
            ''
        );


    cleaned =
        cleaned.replace(
            /^#\s*/gm,
            ''
        );


    cleaned =
        cleaned.replace(
            /^---$/gm,
            ''
        );


    return cleaned.trim();

}


// =============================================================
// RULE-BASED FALLBACK
// =============================================================
function showFallbackSummary(
    data,
    reason
) {

    setAISummaryTitle(
        '✨ Manager Insight Summary'
    );


    setAISummaryText(
        buildManagerSummary(
            data
        )
    );


    setAISummaryMeta(
        reason ||
        'Verified SmartAttend attendance statistics'
    );

}


// =============================================================
// SUMMARY TITLE
// =============================================================
function setAISummaryTitle(text) {

    setText(
        'aiSummaryTitle',
        text
    );

}


// =============================================================
// SUMMARY TEXT
// =============================================================
function setAISummaryText(text) {

    setText(
        'aiSummaryText',
        text || ''
    );

}


// =============================================================
// SUMMARY META
// =============================================================
function setAISummaryMeta(text) {

    setText(
        'aiSummaryMeta',
        text || ''
    );

}


// =============================================================
// VERIFIED RULE-BASED SUMMARY
// =============================================================
function buildManagerSummary(data) {

    var s =
        data.summary || {};


    var period =
        data.period || {};


    var messages = [];


    messages.push(
        'The team has ' +
        Number(
            s.total_employees || 0
        ) +
        ' active employees and ' +
        Number(
            s.total_attendance_records || 0
        ) +
        ' attendance records during the last ' +
        Number(
            period.days || 7
        ) +
        ' days.'
    );


    if (
        Number(
            s.late_records || 0
        ) > 0
    ) {

        messages.push(
            Number(
                s.late_records
            ) +
            ' late attendance record(s) were detected.'
        );

    }


    if (
        Number(
            s.insufficient_hours_records || 0
        ) > 0
    ) {

        messages.push(
            Number(
                s.insufficient_hours_records
            ) +
            ' record(s) have insufficient working hours.'
        );

    }


    if (
        Number(
            s.total_late_minutes || 0
        ) > 0
    ) {

        messages.push(
            'The team accumulated ' +
            Number(
                s.total_late_minutes
            ) +
            ' late minutes.'
        );

    }


    if (
        Number(
            s.average_working_minutes || 0
        ) > 0
    ) {

        messages.push(
            'Average recorded working time is ' +
            Number(
                s.average_working_minutes
            ) +
            ' minutes.'
        );

    }


    if (
        Number(
            s.late_records || 0
        ) === 0 &&
        Number(
            s.insufficient_hours_records || 0
        ) === 0
    ) {

        messages.push(
            'No significant attendance issues were detected.'
        );

    }


    return messages.join(
        ' '
    );

}


// =============================================================
// EMPLOYEE CARDS
// =============================================================
function renderEmployees(
    employees
) {

    var container =
        document.getElementById(
            'employeeContainer'
        );


    if (!container) {

        return;

    }


    if (
        !employees ||
        employees.length === 0
    ) {

        container.innerHTML =
            '<div class="employee-card">' +
            'No employees are assigned to this manager.' +
            '</div>';

        return;

    }


    var html = '';


    for (
        var i = 0;
        i < employees.length;
        i++
    ) {

        html +=
            buildEmployeeCard(
                employees[i]
            );

    }


    container.innerHTML =
        html;

}


// =============================================================
// BUILD EMPLOYEE CARD
// =============================================================
function buildEmployeeCard(
    employee
) {

    var stats =
        employee.statistics || {};


    var severity =
        getSeverity(
            stats
        );


    var badgeClass =
        'badge-good';


    if (
        severity ===
        'Needs Attention'
    ) {

        badgeClass =
            'badge-high';

    }
    else if (
        severity ===
        'Monitor'
    ) {

        badgeClass =
            'badge-medium';

    }


    var code =
        employee.employee_code ||
        'No Employee Code';


    var department =
        employee.department ||
        'No Department';


    var shift =
        employee.shift ||
        '-';


    return (

        '<div class="employee-card">' +

            '<div class="employee-header">' +

                '<div>' +

                    '<div class="employee-name">' +

                        escapeHtml(
                            employee.employee ||
                            '-'
                        ) +

                    '</div>' +

                    '<div class="employee-meta">' +

                        escapeHtml(code) +

                        ' • ' +

                        escapeHtml(
                            department
                        ) +

                        ' • ' +

                        escapeHtml(
                            shift
                        ) +

                    '</div>' +

                '</div>' +


                '<div class="badge ' +
                    badgeClass +
                '">' +

                    escapeHtml(
                        severity
                    ) +

                '</div>' +

            '</div>' +


            '<div class="stats-grid">' +

                buildStat(
                    'Records',
                    stats.attendance_records || 0
                ) +

                buildStat(
                    'Present',
                    stats.present || 0
                ) +

                buildStat(
                    'Late',
                    stats.late || 0
                ) +

                buildStat(
                    'Avg Work',
                    (
                        stats.average_working_minutes ||
                        0
                    ) +
                    ' min'
                ) +

                buildStat(
                    'Late Minutes',
                    stats.total_late_minutes || 0
                ) +

            '</div>' +


            '<div class="insight-list">' +

                buildEmployeeInsights(
                    stats
                ) +

            '</div>' +

        '</div>'

    );

}


// =============================================================
// EMPLOYEE RULE INSIGHTS
// =============================================================
function buildEmployeeInsights(
    stats
) {

    var insights =
        stats.insights || [];


    if (
        insights.length === 0
    ) {

        return (

            '<div class="insight-item healthy-insight">' +

                'No major attendance risk detected.' +

            '</div>'

        );

    }


    var html = '';


    for (
        var i = 0;
        i < insights.length;
        i++
    ) {

        html +=

            '<div class="insight-item">' +

                escapeHtml(
                    insights[i]
                ) +

            '</div>';

    }


    return html;

}


// =============================================================
// SEVERITY
// =============================================================
function getSeverity(
    stats
) {

    var late =
        Number(
            stats.late || 0
        );


    var insufficient =
        Number(
            stats.insufficient_hours || 0
        );


    var lateMinutes =
        Number(
            stats.total_late_minutes || 0
        );


    if (
        late >= 2 ||
        insufficient >= 2 ||
        lateMinutes >= 120
    ) {

        return 'Needs Attention';

    }


    if (
        late > 0 ||
        insufficient > 0 ||
        lateMinutes > 0
    ) {

        return 'Monitor';

    }


    return 'Healthy';

}


// =============================================================
// STAT BOX
// =============================================================
function buildStat(
    label,
    value
) {

    return (

        '<div class="stat-box">' +

            '<div class="stat-label">' +

                escapeHtml(
                    label
                ) +

            '</div>' +

            '<div class="stat-value">' +

                escapeHtml(
                    String(value)
                ) +

            '</div>' +

        '</div>'

    );

}


// =============================================================
// FORMAT DATE
// =============================================================
function formatDate(
    value
) {

    if (!value) {

        return '-';

    }


    var parts =
        value.split('-');


    if (
        parts.length !== 3
    ) {

        return value;

    }


    return (
        parts[2] +
        '-' +
        parts[1] +
        '-' +
        parts[0]
    );

}


// =============================================================
// DOM HELPERS
// =============================================================
function setText(
    id,
    value
) {

    var element =
        document.getElementById(
            id
        );


    if (element) {

        element.textContent =
            value === null ||
            value === undefined
                ? ''
                : String(value);

    }

}


function setDisplay(
    id,
    value
) {

    var element =
        document.getElementById(
            id
        );


    if (element) {

        element.style.display =
            value;

    }

}


// =============================================================
// PAGE ERROR
// =============================================================
function showPageError(
    message
) {

    var loadingBox =
        document.getElementById(
            'loadingBox'
        );


    if (!loadingBox) {

        return;

    }


    loadingBox.style.display =
        'block';


    loadingBox.className =
        'error';


    loadingBox.textContent =
        message;

}


// =============================================================
// HTML ESCAPE
// =============================================================
function escapeHtml(
    value
) {

    return String(
        value === null ||
        value === undefined
            ? ''
            : value
    )

    .replace(
        /&/g,
        '&amp;'
    )

    .replace(
        /</g,
        '&lt;'
    )

    .replace(
        />/g,
        '&gt;'
    )

    .replace(
        /"/g,
        '&quot;'
    )

    .replace(
        /'/g,
        '&#039;'
    );

}
